{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.ObjectInputSchema",
  "description": "Schema for an object input with named properties.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the object.",
      "type": [
        "string",
        "null"
      ]
    },
    "properties": {
      "description": "Schema for each property in the object.",
      "type": "object",
      "additionalProperties": {
        "$ref": "functions.expression.InputSchema"
      }
    },
    "required": {
      "description": "List of property names that must be present.",
      "type": [
        "array",
        "null"
      ],
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "properties"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.MessageExpression",
  "description": "A message with expressions for dynamic content.\n\nThis is the expression variant of [`Message`] used in function definitions\nwhere message content can be computed from the function input at runtime.\nSupports both JMESPath and Starlark expressions.",
  "oneOf": [
    {
      "type": "object",
      "properties": {
        "role": {
          "type": "string",
          "const": "developer"
        }
      },
      "$ref": "agent.completions.message.DeveloperMessageExpression",
      "required": [
        "role"
      ]
    },
    {
      "type": "object",
      "properties": {
        "role": {
          "type": "string",
          "const": "system"
        }
      },
      "$ref": "agent.completions.message.SystemMessageExpression",
      "required": [
        "role"
      ]
    },
    {
      "type": "object",
      "properties": {
        "role": {
          "type": "string",
          "const": "user"
        }
      },
      "$ref": "agent.completions.message.UserMessageExpression",
      "required": [
        "role"
      ]
    },
    {
      "type": "object",
      "properties": {
        "role": {
          "type": "string",
          "const": "assistant"
        }
      },
      "$ref": "agent.completions.message.AssistantMessageExpression",
      "required": [
        "role"
      ]
    },
    {
      "type": "object",
      "properties": {
        "role": {
          "type": "string",
          "const": "tool"
        }
      },
      "$ref": "agent.completions.message.ToolMessageExpression",
      "required": [
        "role"
      ]
    }
  ]
}
